from pathlib import Path
import base64
out=Path('.codex-run/mobile-info-options')
urls=['data:image/webp;base64,'+base64.b64encode(Path('public/assets/characters/portraits/'+n+'.webp').read_bytes()).decode() for n in ['aemeath','sigrika','denia']]
css='''*{box-sizing:border-box}body{margin:0;background:#f1ebe1;color:#443128;font-family:"Microsoft YaHei",sans-serif}header{padding:20px 24px;background:#fffaf0;border-bottom:1px solid #c9b9a8}h1{font-size:20px;margin:0 0 8px}p{font-size:12px;color:#806d5d;margin:8px 0;line-height:1.7}nav{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}button,select{font:inherit;font-size:12px;color:inherit;background:#fffaf0;border:1px solid #c2b09d;border-radius:7px;padding:8px 11px;cursor:pointer}button[aria-pressed=true]{background:#443128;color:#fffaf0}main{padding:24px;display:flex;gap:30px;align-items:flex-start}.phone{width:390px;flex:none;background-color:#fff7ef;background-image:linear-gradient(#b9d6d133 1px,transparent 1px),linear-gradient(90deg,#b9d6d133 1px,transparent 1px);background-size:18px 18px;border:1px solid #c6b6a6;border-radius:20px;padding:16px 10px 20px}.label{font-size:11px;color:#8a7261;letter-spacing:1px;margin:8px 4px 18px}.card{position:relative;display:grid;gap:5px 9px;isolation:isolate;margin-bottom:26px}.portrait{grid-area:art;position:relative;align-self:center;width:100%;height:94px;z-index:1}.single:before{content:'';position:absolute;inset:24px 5px 0;background:#d7ebe5;border:1px solid #6f5a4d;border-radius:45% 45% 5px 5px;rotate:-5deg;box-shadow:3px 3px #c1dcd5}.single img{position:absolute;width:115%;height:112%;object-fit:contain;bottom:0;left:-7%}.team{filter:drop-shadow(2px 3px 0 #44312833)}.piece{position:absolute;inset:5px 0;overflow:hidden;background:#fff0c7;--left:-18.333%}.piece:nth-child(1){clip-path:polygon(0 7%,40% 0,22% 94%,0 100%)}.piece:nth-child(2){--left:15%;background:#e2f2ec;clip-path:polygon(44% 3%,75% 0,55% 100%,25% 97%)}.piece:nth-child(3){--left:48.333%;background:#f4e5ea;clip-path:polygon(79% 5%,100% 0,100% 96%,59% 100%)}.piece img{position:absolute;left:var(--left);width:70%;height:100%;object-fit:cover}.identity{grid-area:id;display:flex;gap:6px;align-items:center;min-width:0;font-size:12px}.username{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rank{font-size:10px;margin-left:auto;white-space:nowrap}.stone{width:11px;height:11px;flex:none;border-radius:50%;background:radial-gradient(circle at 35% 25%,#6d6d6d,#141414);box-shadow:0 0 0 1px #44312833}.white{background:radial-gradient(circle at 30% 20%,white,#c5c8ce)}.timer{grid-area:clock;display:flex;align-items:center;justify-content:space-between;gap:8px;white-space:nowrap}.timer small{font-size:9px;color:#806d5d}.timer strong{font-size:29px;line-height:1.05;font-variant-numeric:tabular-nums;letter-spacing:-1px}.stats{grid-area:stats;display:flex;gap:10px;font-size:10px;white-space:nowrap;align-items:center;color:#806d5d}.stats b{color:#443128;margin-left:3px}.skill{grid-area:skill;display:flex;align-items:center;justify-content:space-between;border:0;padding:3px 0;background:transparent;text-align:left;font-size:11px;min-width:0;gap:6px}.skill span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.skill b{font-size:10px;white-space:nowrap}.skill:focus-visible{outline:2px solid #8e6e42}.a .card{grid-template-columns:100px minmax(0,1fr);grid-template-areas:'art id' 'art clock' 'art stats' 'art skill';grid-template-rows:20px 30px 17px 20px;padding:7px 10px 7px 0}.a .card:before{content:'';position:absolute;inset:0 0 0 64px;background:#fffaf0;border:1.5px solid #5c483b;border-radius:12px;z-index:-1;box-shadow:2px 2px #5c483b}.a .active:before{background:#fff0b7}.a .timer strong{margin-left:auto}.a .skill{border-top:1px solid #44312822}.b .card{grid-template-columns:96px minmax(0,1fr) 83px;grid-template-areas:'art id id' 'art stats clock' 'art skill clock';grid-template-rows:24px 29px 30px;padding:8px 8px 8px 0}.b .card:before{content:'';position:absolute;inset:0 0 0 48px;background:#fffaf0;border:1px solid #8b7261;border-radius:12px;z-index:-1}.b .timer{flex-direction:column;justify-content:center;gap:5px;padding:8px 4px;background:#efe9dd;border:1.5px solid #5c483b;border-radius:10px;box-shadow:2px 2px #5c483b}.b .active .timer{background:#ffe69d}.b .timer strong{font-size:25px}.b .stats{gap:7px;flex-wrap:wrap;align-content:center;line-height:1.2}.b .skill{font-size:10px}.c .card{grid-template-columns:94px minmax(0,1fr);grid-template-areas:'art id' 'art clock' 'stats skill';grid-template-rows:26px 53px 29px;padding:9px 10px 0;background:#fffaf0;border:1.5px solid #5c483b;border-radius:12px;box-shadow:3px 3px #d4c3ad;gap:4px 12px}.c .portrait{height:90px}.c .timer{justify-content:flex-start;align-items:flex-end;padding-bottom:7px}.c .timer strong{order:-1;font-size:34px}.c .timer small{margin-bottom:3px}.c .stats{gap:7px;grid-column:1/2;font-size:9px;border-top:1px solid #ccbba6;padding-top:3px}.c .skill{border-top:1px solid #ccbba6;padding-top:3px}.c .active{border-top:4px solid #d5aa48}.foot{font-size:11px;color:#806d5d;margin:6px 4px}.explain{max-width:270px;padding-top:4px}.explain h2{font-size:17px}.explain p{font-size:13px}.controls{margin-top:20px;display:flex;gap:7px;flex-wrap:wrap}dialog{max-width:300px;border:1px solid #655045;border-radius:12px;background:#fffaf0;color:#443128;padding:20px}dialog::backdrop{background:#44312844}@media(max-width:700px){main{padding:16px 8px;display:block}.phone{max-width:100%}.explain{max-width:390px;margin:auto}}'''
def card(team,active=False):
 art='<div class="portrait team">'+''.join('<div class="piece"><img alt="角色头像" src="'+u+'"></div>' for u in urls)+'</div>' if team else '<div class="portrait single"><img alt="爱弥斯" src="'+urls[0]+'"></div>'
 return '<article class="card '+('active' if active else '')+'">'+art+'<div class="identity"><i class="stone '+('' if team else 'white')+'"></i><span class="username">'+('moming' if team else '春日里的棋友')+'</span><span class="rank">3段</span></div><div class="timer"><small>'+('正在用时' if active else '剩余时间')+'</small><strong>'+('04:32' if active else '08:16')+'</strong></div><div class="stats"><span>提子<b>2</b></span><span>除子<b>1</b></span><span>耗子<b>0</b></span></div><button class="skill"><span>✧ 共鸣技能</span><b>剩余 1 次 ›</b></button></article>'
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>移动对弈信息区 · 三版样板</title><style>'+css+'</style><header><h1>移动对弈信息区 · 三版样板</h1><p>同一套信息，三种排布 · 上方单人 / 下方队际 · 黄色表示当前回合</p><nav><button data-v="a" aria-pressed="true">A · 紧凑纸条</button><button data-v="b">B · 独立棋钟</button><button data-v="c">C · 分层信息卡</button></nav></header><main><section class="phone a"><div class="label">单人 · 非当前回合</div>'+card(False)+'<div class="label">队际 · 当前回合</div>'+card(True,True)+'<div class="foot">以上为信息区样板，棋盘位于信息区下方。</div></section><aside class="explain"><h2></h2><p class="description"></p><div class="controls"><select aria-label="屏幕宽度"><option value="390">390px 手机</option><option value="320">320px 窄屏</option><option value="430">430px 宽屏</option></select><button id="turn">切换回合</button><button id="long">测试长用户名</button></div><p>可点击技能查看样板说明。</p></aside></main><dialog><strong>技能详情入口</strong><p>正式接入时沿用当前角色的真实技能说明、次数与超频内容。本页仅演示浮层交互。</p><button id="close">关闭</button></dialog>'+r'''<script>const data={a:["A · 紧凑纸条","头像在左，右侧纵向排布身份、计时、统计和技能。延续现有纸条风格，占用高度最少。"],b:["B · 独立棋钟","计时器单独放在右侧，头像和技能留在左侧。当前回合只点亮棋钟，找时间最快；窄屏文字空间较紧。"],c:["C · 分层信息卡","上方集中身份与大计时，下方独立一行放统计和技能。层次清楚，卡片比另外两版更高。"]};function show(v){document.querySelector('.phone').className='phone '+v;document.querySelector('h2').textContent=data[v][0];document.querySelector('.description').textContent=data[v][1];document.querySelectorAll('[data-v]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.v===v))}document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>show(b.dataset.v));document.querySelector('select').onchange=e=>document.querySelector('.phone').style.width=e.target.value+'px';document.querySelector('#turn').onclick=()=>document.querySelectorAll('.card').forEach(c=>{c.classList.toggle('active');c.querySelector('small').textContent=c.classList.contains('active')?'正在用时':'剩余时间'});document.querySelector('#long').onclick=()=>document.querySelectorAll('.username').forEach(n=>n.textContent=n.textContent.length>12?'moming':'这是一个用于测试排版的很长的用户名');document.querySelectorAll('.skill').forEach(b=>b.onclick=()=>document.querySelector('dialog').showModal());document.querySelector('#close').onclick=()=>document.querySelector('dialog').close();show('a');</script></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
